from pathlib import Path
import subprocess,re,shutil,zipfile,json,hashlib
root=Path('/workspace/work/3cx')
dist=Path('/workspace/work/ti-downloads/dist')
target=dist/'3cx';target.mkdir(exist_ok=True)
files=['3cx_full_talk.docx','3cx_full_talk.pdf','3cx_full_talk.md','3cx_speech.md','demo_source.png','demo_fields.png','timing.json']
for name in files:shutil.copy2(root/name,target/name)
with zipfile.ZipFile(target/'3cx_materials.zip','w',zipfile.ZIP_DEFLATED) as z:
 for name in files:z.write(root/name,arcname=name)
fragment=subprocess.run(['pandoc',str(root/'3cx_full_talk.md'),'-t','html5','--wrap=none'],check=True,capture_output=True,text=True).stdout
fragment=re.sub(r'^<h1[^>]*>.*?</h1>\n','',fragment,count=1,flags=re.S)
fragment=re.sub(r'(<table[^>]*>.*?</table>)',r'<div class="table-scroll">\1</div>',fragment,flags=re.S)
fragment=fragment.replace('<a href="http','<a target="_blank" rel="noopener" href="http')
toc=''.join(f'<a href="#{a}">{re.sub("<[^>]+>","",b)}</a>' for a,b in re.findall(r'<h2 id="([^"]+)">(.*?)</h2>',fragment,re.S))
html='''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Самостоятельный доклад о 3CX для младших курсов: полная речь на 25 минут, бриф 14 слайдов, демонстрация, памятка и источники."><title>Дело об обновлении 3CX — полный доклад</title><link rel="stylesheet" href="style.css"></head>
<body><main><header id="top"><a class="back" href="../">← Все материалы</a><p class="eyebrow">THREAT INTELLIGENCE · ДЛЯ МЛАДШИХ КУРСОВ</p><h1>Дело об обновлении <span>3CX</span></h1><p class="lead">«Программа официальная и подписанная. Почему сработала защита?»</p><p class="intro">Самостоятельный доклад: открываем улики по одной, уточняем вопрос и возвращаемся к собственным данным.</p><div class="facts"><span>25 минут</span><span>14 слайдов в брифе</span><span>Полная речь</span><span>Компания и спикер — нейтральные поля</span></div><nav class="downloads" aria-label="Скачать материалы"><a class="primary" href="3cx_full_talk.docx" download="Доклад-3CX.docx">Редактировать в DOCX ↓</a><a href="3cx_full_talk.pdf" target="_blank" rel="noopener">Открыть PDF ↗</a><a href="3cx_materials.zip" download="Материалы-3CX.zip">Все материалы ZIP ↓</a><a href="3cx_speech.md" download="Речь-3CX.md">Только речь ↓</a></nav><div class="evidence"><div><small>ЗНАЕМ</small><p>Реальный инцидент 2023 года и первичные исследования.</p></div><div><small>ПРЕДПОЛАГАЕМ</small><p>Учебное устройство могло получить затронутый комплект.</p></div><div><small>ПРОВЕРЯЕМ</small><p>Компоненты, исполнение и сетевые действия.</p></div></div></header><section class="contents" aria-label="Содержание"><p>Читать полный документ</p>'''+toc+'''</section><article class="document">'''+fragment+'''</article><footer><a href="#top">↑ К файлам</a><a href="3cx_full_talk.md" download="Доклад-3CX.md">Исходник Markdown ↓</a><p>DOCX содержит встроенные резервные кадры. В ZIP — документ, PDF, исходники, кадры и тайминг.</p></footer></main></body></html>'''
(target/'index.html').write_text(html)
(target/'style.css').write_text('''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#eff3f4;color:#122d39;font-family:Arial,Helvetica,sans-serif;line-height:1.65}main{max-width:1100px;margin:auto;padding:40px 32px 60px}.back{color:#386875;text-decoration:none;font-size:14px}.eyebrow{margin-top:50px;font-size:12px;font-weight:bold;letter-spacing:1.6px;color:#38747f}h1{font-size:clamp(34px,5vw,62px);line-height:1.1;letter-spacing:-2px;margin:20px 0 26px;max-width:850px}h1 span{color:#157984}.lead{font-size:clamp(20px,2.5vw,29px);max-width:860px;line-height:1.4}.intro{max-width:770px;color:#42616c;font-size:17px}.facts{display:flex;flex-wrap:wrap;gap:10px;margin:26px 0}.facts span{border:1px solid #c6d5db;border-radius:30px;padding:5px 13px;font-size:13px}.downloads{display:flex;flex-wrap:wrap;gap:12px;margin:30px 0}.downloads a{padding:12px 18px;border:1px solid #93b1bd;color:#174452;text-decoration:none;border-radius:7px;font-size:14px;font-weight:bold}.downloads a:hover{background:#dce9ed}.downloads .primary{background:#126b79;border-color:#126b79;color:white}.downloads .primary:hover{background:#0d5561}.evidence{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:38px 0 50px}.evidence div{padding:22px 24px;border-top:3px solid #238b94;background:white;border-radius:2px 2px 8px 8px}.evidence div:nth-child(2){border-top-color:#cfa963}.evidence div:nth-child(3){border-top-color:#69748c}.evidence small{font-size:11px;letter-spacing:1.5px;font-weight:bold;color:#347b85}.evidence p{font-size:15px;margin:10px 0 0}.contents{padding:26px;background:#dfe9ec;border-radius:10px;margin-bottom:28px}.contents p{font-weight:bold;margin:0 0 12px}.contents a{display:block;color:#275a69;text-decoration:none;padding:4px 0;font-size:14px}.contents a:hover{text-decoration:underline}.document{background:white;border:1px solid #dbe4e7;border-radius:10px;padding:50px 50px 35px;color:#203843;font-size:16px;overflow:hidden}.document h2{font-size:28px;line-height:1.3;margin:56px 0 24px;scroll-margin-top:22px;color:#155c6e}.document h2:first-of-type{margin-top:35px}.document h3{font-size:20px;line-height:1.4;margin-top:30px;color:#275568}.document p{margin:16px 0}.document a{color:#176f82;overflow-wrap:anywhere}.document code{font-family:Consolas,monospace;font-size:.87em;overflow-wrap:anywhere}.document pre{padding:18px;background:#edf2f5;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5;border-radius:6px}.document img{max-width:100%;height:auto;display:block;border-radius:6px}.document figure{margin:28px 0}.document figcaption{font-size:13px;color:#526c77;margin-top:9px}.table-scroll{overflow-x:auto;margin:26px 0}table{width:100%;min-width:570px;border-collapse:collapse;font-size:13px;line-height:1.55}th,td{padding:11px 13px;vertical-align:top;text-align:left;border:1px solid #d2e0e5}th{background:#e0edf0;font-weight:bold}tr:nth-child(even){background:#f6f9fa}.document blockquote{margin-left:0;border-left:3px solid #4295a0;padding-left:20px;color:#40616d}.document li{margin:9px 0}footer{display:flex;flex-wrap:wrap;gap:22px;padding:28px 2px;font-size:14px}footer a{color:#1c6476}footer p{width:100%;font-size:13px;color:#57727d;margin:0}a:focus-visible{outline:3px solid #ce9850;outline-offset:4px}@media(max-width:700px){main{padding:24px 18px}.eyebrow{margin-top:35px}h1{letter-spacing:-1px}.evidence{grid-template-columns:1fr;gap:9px}.evidence div{padding:16px 20px}.document{padding:26px 22px;font-size:15px}.document h2{font-size:23px}.document h3{font-size:18px}.downloads a{flex:1 1 150px;text-align:center}.contents{padding:20px}}@media print{body{background:white}main{max-width:none;padding:0}header,.contents,footer{display:none}.document{border:0;padding:0}h2,h3{break-after:avoid}table{font-size:11px}.table-scroll{overflow:visible}a{color:inherit}}''')
home=dist/'index.html';old=home.read_text()
if 'href="3cx/"' not in old:
 old=old.replace('    <footer>','    <section class="case-link"><p>Новый самостоятельный доклад</p><h2>Дело об обновлении 3CX</h2><p>Полная речь для младших курсов, бриф 14 слайдов, демонстрация и памятка.</p><a href="3cx/">Открыть материалы 3CX →</a></section>\n    <footer>')
 home.write_text(old)
css=dist/'style.css';old=css.read_text()
if '.case-link{' not in old:css.write_text(old+'\n.case-link{margin-top:34px;padding:28px;border:1px solid #304854;border-radius:12px;background:#11252d}.case-link p{color:#b7cbd1;font-size:14px}.case-link h2{color:#fff;font-size:25px;margin:10px 0}.case-link a{display:inline-block;margin-top:12px;color:#77ded8;font-weight:bold}\n')
# Validate local assets, internal section links and copies.
for match in re.findall(r'(?:href|src)="([^"]+)"',html):
 if match.startswith(('http','#')) or match=='../':continue
 assert (target/match).exists(),match
ids=set(re.findall(r'id="([^"]+)"',html))
for a in re.findall(r'href="#([^"]+)"',html):assert a in ids,a
for name in files:assert hashlib.sha256((root/name).read_bytes()).digest()==hashlib.sha256((target/name).read_bytes()).digest()
assert html.count('<table')==8 and html.count('</table>')==8
print(json.dumps({'route':'/3cx/','files':len(files),'html_bytes':len(html.encode()),'toc_sections':len(re.findall('<h2 ',fragment)),'zip_bytes':(target/'3cx_materials.zip').stat().st_size},ensure_ascii=False))
